=== FILE: rr_arbiter.v ===
`timescale 1ns/1ps
`default_nettype none

// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md / microarchitecture.md (rr_arbiter).
//  * grant is combinational from req and the priority pointer (same-cycle grant).
//  * The winner is the first requester with req high at or after ptr, searching
//    upwards and wrapping from N-1 to 0.
//  * On a rising edge with a grant (and rst_n high), ptr moves to one past the
//    winner, wrapping at N-1 (not at a power of two).
//  * rst_n is synchronous, active low; ptr resets to 0; grant is not gated by reset.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    reg [PW-1:0] ptr;        // index of the requester with the highest priority
    reg [PW-1:0] nxt_ptr;    // one past the winner, wrapped at N-1
    reg [PW-1:0] idx;        // index of loop step i, in pointer width
    reg          any_grant;  // a requester was granted this cycle
    integer      i;

    // Wrapping priority search, written as two ordered passes:
    //   pass 1: requesters at or above ptr, lowest index first;
    //   pass 2: only if pass 1 found none, requesters below ptr, lowest first.
    // Every output has a default, so this is pure combinational logic.
    always @* begin
        grant     = {N{1'b0}};
        nxt_ptr   = ptr;
        any_grant = 1'b0;

        idx = {PW{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            if (!any_grant && req[i] && (idx >= ptr)) begin
                any_grant = 1'b1;
                grant[i]  = 1'b1;
                nxt_ptr   = (i == N - 1) ? {PW{1'b0}} : idx + 1'b1;
            end
            idx = idx + 1'b1;
        end

        idx = {PW{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            if (!any_grant && req[i] && (idx < ptr)) begin
                any_grant = 1'b1;
                grant[i]  = 1'b1;
                nxt_ptr   = (i == N - 1) ? {PW{1'b0}} : idx + 1'b1;
            end
            idx = idx + 1'b1;
        end
    end

    // Pointer update: moves only on a grant, to one past the winner.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else if (any_grant) begin
            ptr <= nxt_ptr;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven in this task).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @* begin
        // one-hot or zero
        assert ((grant & (grant - 1'b1)) == {N{1'b0}});
        // only to a requester
        assert ((grant & ~req) == {N{1'b0}});
        // work conserving
        assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
    end

    // pointer is 0 after reset
    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert (ptr == {PW{1'b0}});
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
`timescale 1ns/1ps

// Self-checking testbench for rr_arbiter.
// Runs two arbiters side by side (N=4 and N=5). Each unit checks grant on
// every rising edge against a reference pointer model, checks the one-hot /
// only-to-a-requester / work-conserving properties, checks that no held
// request waits N cycles, runs directed and random stimulus, and fails the
// run if any case from the interface spec was not reached.

module rr_arbiter_tb_unit #(
    parameter integer N    = 4,
    parameter integer SEED = 1
) (
    input  wire        clk,
    output reg         done,
    output wire [31:0] n_pass,
    output wire [31:0] n_fail
);

    localparam [N-1:0] ALL  = {N{1'b1}};
    localparam [N-1:0] NONE = {N{1'b0}};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Check counters: chk_* written only by the edge checker, stim_* only by
    // the stimulus process.
    integer chk_pass  = 0;
    integer chk_fail  = 0;
    integer stim_pass = 0;
    integer stim_fail = 0;

    assign n_pass = chk_pass + stim_pass;
    assign n_fail = chk_fail + stim_fail;

    function [N-1:0] one;
        input integer idx;
        begin
            one      = {N{1'b0}};
            one[idx] = 1'b1;
        end
    endfunction

    // ------------------------------------------------------------------
    // Reference model and per-edge checker
    // ------------------------------------------------------------------
    reg          checking = 1'b0;
    integer      ref_ptr  = 0;
    reg  [N-1:0] expected;
    reg  [N-1:0] prev_req = {N{1'b0}};
    reg          found;
    reg          fair_bad;
    integer      win;
    integer      k;
    integer      j;
    integer      wait_cnt [0:N-1];

    reg          cov_idle        = 1'b0;
    reg          cov_all         = 1'b0;
    reg          cov_maxwait     = 1'b0;
    reg          cov_held        = 1'b0;
    reg          cov_rst_traffic = 1'b0;
    reg  [N-1:0] cov_alone       = {N{1'b0}};

    always @(posedge clk) begin
        // Reference grant: first requester at or after ref_ptr, wrapping at N.
        expected = {N{1'b0}};
        found    = 1'b0;
        win      = 0;
        for (k = 0; k < N; k = k + 1) begin
            j = (ref_ptr + k) % N;
            if (!found && req[j]) begin
                found       = 1'b1;
                expected[j] = 1'b1;
                win         = j;
            end
        end

        if (checking) begin
            // 1. grant matches the reference pointer model
            if (grant === expected) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("N=%0d t=%0t: grant %b, expected %b (req %b, rst_n %b, model ptr %0d)",
                       N, $time, grant, expected, req, rst_n, ref_ptr);
            end

            // 2. one-hot or zero, only to a requester, work conserving
            if (((grant & (grant - 1'b1)) === NONE) &&
                ((grant & ~req) === NONE) &&
                ((req === NONE) || (grant !== NONE))) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("N=%0d t=%0t: grant %b for req %b is not one-hot-or-zero, only to a requester, and work conserving",
                       N, $time, grant, req);
            end

            // 3. fairness: a held request waits at most N-1 cycles
            fair_bad = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                if (!rst_n || !req[k] || grant[k]) begin
                    wait_cnt[k] = 0;
                end else begin
                    if ((wait_cnt[k] >= 1) && (((req ^ prev_req) & ~one(k)) != NONE))
                        cov_held = 1'b1;
                    wait_cnt[k] = wait_cnt[k] + 1;
                    if (wait_cnt[k] > N - 1) begin
                        fair_bad = 1'b1;
                        $error("N=%0d t=%0t: requester %0d has waited %0d cycles with req held (limit %0d)",
                               N, $time, k, wait_cnt[k], N - 1);
                    end
                    if (wait_cnt[k] == N - 1)
                        cov_maxwait = 1'b1;
                end
            end
            if (fair_bad) chk_fail = chk_fail + 1;
            else          chk_pass = chk_pass + 1;

            // coverage of interface-spec cases
            if (rst_n) begin
                if (req === NONE) cov_idle = 1'b1;
                if (req === ALL)  cov_all  = 1'b1;
                for (k = 0; k < N; k = k + 1) begin
                    if ((req === one(k)) && (grant === one(k)))
                        cov_alone[k] = 1'b1;
                end
            end else if ((req !== NONE) && (ref_ptr != 0)) begin
                cov_rst_traffic = 1'b1;
            end
        end else begin
            for (k = 0; k < N; k = k + 1)
                wait_cnt[k] = 0;
        end

        prev_req = req;

        // Reference pointer update
        if (!rst_n)
            ref_ptr <= 0;
        else if (found)
            ref_ptr <= (win + 1) % N;
    end

    // ------------------------------------------------------------------
    // Stimulus with explicit directed checks
    // ------------------------------------------------------------------
    integer seed;
    integer c;
    integer h;
    integer r;

    // Checks grant shortly after the inputs were applied at a falling edge.
    task expect_grant;
        input [N-1:0] exp_g;
        begin
            #1;
            if (grant === exp_g) begin
                stim_pass = stim_pass + 1;
            end else begin
                stim_fail = stim_fail + 1;
                $error("N=%0d t=%0t: directed check: grant %b, expected %b (req %b, rst_n %b)",
                       N, $time, grant, exp_g, req, rst_n);
            end
        end
    endtask

    task cover_check;
        input          flag;
        input [8*48-1:0] what;
        begin
            if (flag === 1'b1) begin
                stim_pass = stim_pass + 1;
            end else begin
                stim_fail = stim_fail + 1;
                $error("N=%0d: coverage case not reached: %0s", N, what);
            end
        end
    endtask

    initial begin
        seed  = SEED;
        done  = 1'b0;
        rst_n = 1'b0;
        req   = NONE;

        @(posedge clk);
        @(negedge clk);
        checking = 1'b1;
        expect_grant(NONE);

        // 1. Requests during reset: grant follows req, pointer stays at 0.
        @(negedge clk); req = ALL;      expect_grant(one(0));
        @(negedge clk); req = one(N-1); expect_grant(one(N-1));
        @(negedge clk); req = ALL;      expect_grant(one(0));

        // 2. Release reset with everyone requesting: strict rotation 0..N-1.
        @(negedge clk); rst_n = 1'b1; req = ALL; expect_grant(one(0));
        for (c = 1; c < 3 * N; c = c + 1) begin
            @(negedge clk); req = ALL; expect_grant(one(c % N));
        end
        // pointer is back at 0

        // 3. No requests.
        repeat (3) begin
            @(negedge clk); req = NONE; expect_grant(NONE);
        end

        // 4. Each requester alone.
        for (c = 0; c < N; c = c + 1) begin
            repeat (2) begin
                @(negedge clk); req = one(c); expect_grant(one(c));
            end
            @(negedge clk); req = NONE; expect_grant(NONE);
        end
        // pointer is 0

        // 5. Longest fair wait: requester h sits just behind the pointer
        //    while everyone requests; it waits N-1 cycles, then is granted.
        for (h = 0; h < N; h = h + 1) begin
            @(negedge clk); req = one(h); expect_grant(one(h));
            for (c = 1; c <= N - 1; c = c + 1) begin
                @(negedge clk); req = ALL; expect_grant(one((h + c) % N));
            end
            @(negedge clk); req = ALL; expect_grant(one(h));
        end
        // pointer is 0

        // 6a. Directed: requester N-1 held among changing others (needs N >= 4).
        @(negedge clk); req = one(0) | one(1) | one(N-1); expect_grant(one(0));
        @(negedge clk); req = one(1) | one(2) | one(N-1); expect_grant(one(1));
        @(negedge clk); req = one(2) | one(N-1);          expect_grant(one(2));
        @(negedge clk); req = one(0) | one(N-1);          expect_grant(one(N-1));
        // pointer is 0

        // 7a. Directed reset during traffic, with the pointer away from 0.
        @(negedge clk); req = one(1); expect_grant(one(1));              // ptr -> 2
        @(negedge clk); rst_n = 1'b0; req = ALL; expect_grant(one(2));   // grant from ptr 2
        @(negedge clk); req = ALL; expect_grant(one(0));                 // ptr reset to 0
        @(negedge clk); req = ALL; expect_grant(one(0));                 // frozen in reset
        @(negedge clk); rst_n = 1'b1; req = ALL; expect_grant(one(0));
        @(negedge clk); req = ALL; expect_grant(one(1));

        // 6b. Random: each requester held while the others change at random.
        for (h = 0; h < N; h = h + 1) begin
            for (c = 0; c < 4 * N; c = c + 1) begin
                @(negedge clk);
                r   = $random(seed);
                req = r[N-1:0] | one(h);
            end
        end

        // 7b. Random traffic with reset pulses.
        for (c = 0; c < 300; c = c + 1) begin
            @(negedge clk);
            r     = $random(seed);
            req   = r[N-1:0];
            rst_n = !(((c >= 100) && (c < 102)) || (c == 200));
        end

        @(negedge clk); rst_n = 1'b1; req = NONE; expect_grant(NONE);
        @(negedge clk);
        checking = 1'b0;

        // Coverage: every interface-spec case must have been reached.
        cover_check(cov_idle,        "no requests");
        cover_check(cov_all,         "everyone requesting");
        cover_check(cov_maxwait,     "longest fair wait (N-1 cycles)");
        cover_check(cov_held,        "held request among changing others");
        cover_check(cov_rst_traffic, "reset during traffic");
        for (c = 0; c < N; c = c + 1)
            cover_check(cov_alone[c], "each requester alone");

        done = 1'b1;
    end

endmodule


module rr_arbiter_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire        d4;
    wire        d5;
    wire [31:0] p4;
    wire [31:0] f4;
    wire [31:0] p5;
    wire [31:0] f5;

    rr_arbiter_tb_unit #(.N(4), .SEED(32'h00001b70)) u_n4 (
        .clk    (clk),
        .done   (d4),
        .n_pass (p4),
        .n_fail (f4)
    );

    rr_arbiter_tb_unit #(.N(5), .SEED(32'h00000bad)) u_n5 (
        .clk    (clk),
        .done   (d5),
        .n_pass (p5),
        .n_fail (f5)
    );

    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        cycles;
    integer        timeout_fail;

    initial begin
        nonce = {8*64{1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";

        cycles = 0;
        @(posedge clk);
        while (!((d4 === 1'b1) && (d5 === 1'b1)) && (cycles < 20000)) begin
            @(posedge clk);
            cycles = cycles + 1;
        end

        timeout_fail = ((d4 === 1'b1) && (d5 === 1'b1)) ? 0 : 1;
        if (timeout_fail != 0)
            $error("timeout: testbench units did not finish within %0d cycles", cycles);

        #1;
        passed = p4 + p5;
        failed = f4 + f5 + timeout_fail;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
